import{_ as a,o as i,c as t,ag as r}from"./chunks/framework.DHSXpJLs.js";const p=JSON.parse('{"title":"界面使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interface.md","filePath":"guide/interface.md","lastUpdated":1790779354000}'),o={name:"guide/interface.md"};function l(d,e,n,c,s,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="界面使用" tabindex="-1">界面使用 <a class="header-anchor" href="#界面使用" aria-label="Permalink to &quot;界面使用&quot;">​</a></h1><p>前端只有两个页面：首页是项目与模型库，点进模型后是查看器页。IFC 模型挂三维查看器，DXF 模型挂二维画布。本文按使用顺序介绍各块界面；怎么改模型见<a href="/SourceAEC/guide/editing">编辑工作流</a>。</p><h2 id="项目与模型库" tabindex="-1">项目与模型库 <a class="header-anchor" href="#项目与模型库" aria-label="Permalink to &quot;项目与模型库&quot;">​</a></h2><p>首页分两块：项目和模型列表。</p><p>新建项目点「新建空白项目（AI 建模）」，填标题，选类型。类型有三种：<code>ifc</code> 是 AI 生成 IFC 模型，<code>cad</code> 是 AI 生成 DXF 图纸，<code>cad-&gt;ifc</code> 是先出图再转 IFC 的完整链路。一个项目对应一个会话。</p><p>历史项目列出所有会话，点进去可以继续对话。删除项目会连带清掉会话记录、方案文件和项目下的所有模型。</p><p>模型列表展示 agent 在项目里生成的每个模型，标明 IFC 还是 DXF、大小、状态和创建时间。状态从 <code>converting</code> 变成 <code>ready</code> 就能点开看；转换失败会显示 <code>failed</code>，可以重试。列表里还可以下载原始文件或删除模型，删除会连带清理转换产物和 Issue。</p><blockquote><p>模型不再由用户直接上传，上传入口已隐藏，模型一律由 agent 在项目会话里生成。</p></blockquote><h2 id="ifc-三维查看器" tabindex="-1">IFC 三维查看器 <a class="header-anchor" href="#ifc-三维查看器" aria-label="Permalink to &quot;IFC 三维查看器&quot;">​</a></h2><p>IFC 模型有两条渲染链路，在界面右上角切换，默认 xeokit：</p><ul><li><strong>xeokit</strong>：加载预转换的 XKT 数据，工具链最全，模型树、剖切、测量、Issue 钉、Diff 着色都在这条链路上。</li><li><strong>web-ifc</strong>：浏览器里直接读 IFC 原件，不等转换。有渲染、旋转、空间树、属性和选中高亮，但没有高级工具。</li></ul><h3 id="模型树与属性" tabindex="-1">模型树与属性 <a class="header-anchor" href="#模型树与属性" aria-label="Permalink to &quot;模型树与属性&quot;">​</a></h3><p>左侧模型树按空间结构组织，从 Site 到 Building 到 Storey 再到构件。支持按名称或 IFC 类型搜索过滤，每个节点可以单独隐藏。点击节点，相机会飞到该构件并高亮。</p><p>右侧属性面板显示选中构件的属性集，可折叠、搜索、复制。属性是只读的——要改值得走脚本，见<a href="/SourceAEC/guide/editing">编辑工作流</a>。</p><h3 id="视图工具" tabindex="-1">视图工具 <a class="header-anchor" href="#视图工具" aria-label="Permalink to &quot;视图工具&quot;">​</a></h3><ul><li>可见性工具栏：隐藏选中、隔离、X-Ray 半透明、重置。</li><li>剖切：三个方向的滑杆，用来切开模型看内部。</li><li>测量：点两个构件量距离，双击结束。</li><li>NavCube 提供方向指示和视图切换。</li></ul><h2 id="dxf-二维画布" tabindex="-1">DXF 二维画布 <a class="header-anchor" href="#dxf-二维画布" aria-label="Permalink to &quot;DXF 二维画布&quot;">​</a></h2><p>DXF 模型走 Canvas 二维画布，图层颜色和线型按 DXF 原语义渲染，坐标保持原图纸坐标系。选中带 key 的实体，面板会出现<strong>定位脚本</strong>按钮，点击跳到生成它的脚本行，和 IFC 侧的定位是同一条链路。</p><h2 id="issue-与-3d-钉" tabindex="-1">Issue 与 3D 钉 <a class="header-anchor" href="#issue-与-3d-钉" aria-label="Permalink to &quot;Issue 与 3D 钉&quot;">​</a></h2><p>审查中发现问题，操作是：</p><ol><li>选中构件，在底部 Issue 面板点「新建 Issue」，填写标题和评论。</li><li>创建时自动带上当前视角和画布截图，3D 钉会投影到构件位置。</li><li>点钉或列表条目，恢复创建时的视角并选中构件。</li><li>Issue 状态在 open、checking、resolved 之间流转。</li></ol><p>底部的「修改历史」标签页按时间倒序展示每次修改：改了哪个实体、哪个字段、旧值新值各是什么。</p><h2 id="ai-对话侧栏" tabindex="-1">AI 对话侧栏 <a class="header-anchor" href="#ai-对话侧栏" aria-label="Permalink to &quot;AI 对话侧栏&quot;">​</a></h2><p>项目会话右侧是可折叠的 AI 对话栏。用自然语言描述需求，agent 就开始建模。消息流里有文本、推理过程和工具调用卡片，ifc-agent 和 cad-agent 的输出分组展示。agent 中途向你提问时，弹框回答即可继续。试运行成功后画布上能直接看到中间结果，详见<a href="/SourceAEC/guide/editing">编辑工作流</a>。</p><h2 id="相关-api" tabindex="-1">相关 API <a class="header-anchor" href="#相关-api" aria-label="Permalink to &quot;相关 API&quot;">​</a></h2><p>项目、会话、模型和 Issue 的接口契约见<a href="/SourceAEC/reference/api-model">模型与审查 API</a>与<a href="/SourceAEC/reference/api-chat">对话 API</a>。</p>',26)])])}const f=a(o,[["render",l]]);export{p as __pageData,f as default};
